cat > scratch_decision_extract.py <<'EOF'
import sys, re, html
from html.parser import HTMLParser
class P(HTMLParser):
    def __init__(s): super().__init__(); s.out=[]; s.skip=0
    def handle_starttag(s,t,a):
        if t in('script','style','noscript'): s.skip+=1
        if t in('p','li','h1','h2','h3','h4','h5','br','div','tr'): s.out.append('\n')
        if t=='li': s.out.append('- ')
        if t=='a':
            h=dict(a).get('href','')
            s.href=h
    def handle_endtag(s,t):
        if t in('script','style','noscript'): s.skip-=1
    def handle_data(s,d):
        if not s.skip: s.out.append(d)
for f in sys.argv[1:]:
    p=P(); p.feed(open(f,encoding='utf-8',errors='replace').read())
    t=''.join(p.out); t=re.sub(r'[ \t]+',' ',t); t=re.sub(r'\n\s*\n+','\n',t)
    open(f.replace('.html','.txt'),'w').write(t)
    print(f, len(t))
EOF
python3 scratch_decision_extract.py scratch_decision_dec.html scratch_decision_policies.html

