import json, sys, time, urllib.parse, urllib.request
qs = sys.argv[1:]
for q in qs:
    for issn in ["2325-9965", "2325-9973"]:
        url = ("https://api.crossref.org/works?query.bibliographic=" + urllib.parse.quote(q)
               + f"&filter=issn:{issn},from-pub-date:2021,type:journal-article&rows=10&select=DOI,title,published")
        for attempt in range(3):
            try:
                d = json.load(urllib.request.urlopen(url, timeout=60)); break
            except Exception as e:
                time.sleep(3); d = None
        if not d: print("FAIL", q, issn); continue
        print(f"## {q} [{issn}] total={d['message']['total-results']}")
        for i in d['message']['items']:
            print(" ", i['DOI'], i.get('published', {}).get('date-parts'), i['title'][0][:110])
EOF
